using System.Text.Json;
using Gravicode.Science.GraviNum;
using Gravicode.Science.SciNet;
using Gravicode.Science.SciNet.Spatial;
using Xunit;
using static Gravicode.Science.Tests.SciNet.SpatialAssert;

namespace Gravicode.Science.Tests.SciNet;

/// <summary>
/// Linkage, fcluster, cophenet, inconsistency and dendrogram pinned against scipy 1.17.1. The
/// fixture was generated by running scipy.cluster.hierarchy on four datasets (random, scipy's
/// own ward example, integer data full of ties and duplicates, and a larger random set) for all
/// seven methods.
/// </summary>
public class HierarchyTests
{
    private static readonly Lazy<JsonDocument> Fixture = new(() =>
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "Gravicode.Science.sln"))) dir = dir.Parent;
        // Scratch builds outside the repository fall back to this source file's own folder.
        var path = dir is not null
            ? Path.Combine(dir.FullName, "tests", "SciNet.Tests", "Cluster", "Fixtures", "hierarchy_scipy_1_17_1.json")
            : Path.Combine(SourceDirectory(), "Fixtures", "hierarchy_scipy_1_17_1.json");
        return JsonDocument.Parse(File.ReadAllText(path));
    });

    private static string SourceDirectory([System.Runtime.CompilerServices.CallerFilePath] string file = "")
        => Path.GetDirectoryName(file)!;

    private static double[] D(JsonElement e) => e.EnumerateArray().Select(v => v.GetDouble()).ToArray();
    private static int[] I(JsonElement e) => e.EnumerateArray().Select(v => v.GetInt32()).ToArray();

    public static TheoryData<int> Cases()
    {
        var t = new TheoryData<int>();
        for (var i = 0; i < Fixture.Value.RootElement.GetProperty("cases").GetArrayLength(); i++) t.Add(i);
        return t;
    }

    private static (JsonElement Case, double[] Y, NdArray X, LinkageMethod Method) Load(int index)
    {
        var c = Fixture.Value.RootElement.GetProperty("cases")[index];
        var ds = Fixture.Value.RootElement.GetProperty("datasets").GetProperty(c.GetProperty("data").GetString()!);
        var x = D(ds.GetProperty("x"));
        var d = ds.GetProperty("d").GetInt32();
        var method = Enum.Parse<LinkageMethod>(c.GetProperty("method").GetString()!, ignoreCase: true);
        return (c, D(ds.GetProperty("y")), new NdArray(x, x.Length / d, d), method);
    }

    private static void SameZ(double[] expected, NdArray z, string what)
    {
        var a = z.ToArray();
        Assert.Equal(expected.Length, a.Length);
        for (var i = 0; i < a.Length; i++)
        {
            if (i % 4 == 2) Close(expected[i], a[i], 1e-12 * Math.Max(1, Math.Abs(expected[i])), $"{what} row {i / 4} distance");
            else Assert.True(expected[i] == a[i], $"{what} row {i / 4} column {i % 4}: expected {expected[i]}, got {a[i]}");
        }
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Linkage_IsIdenticalToScipy(int index)
    {
        var (c, y, x, method) = Load(index);
        var name = $"{c.GetProperty("data").GetString()}/{method}";
        var z = Cluster.Linkage(y, method);
        SameZ(D(c.GetProperty("z")), z, name);
        Assert.True(Cluster.IsValidLinkage(z));
        // From observations, through this library's pdist.
        SameZ(D(c.GetProperty("z")), Cluster.Linkage(x, method), name + " (from X)");
        Assert.Equal(I(c.GetProperty("leaves")), Cluster.LeavesList(z));
        Assert.Equal(I(c.GetProperty("leaves")), Cluster.ToTree(z).PreOrder().ToArray());
        if (c.GetProperty("zopt").ValueKind != JsonValueKind.Null)
        {
            // scipy 1.17.1's optimal_leaf_ordering is not always optimal (on 9-point random sets
            // it missed the minimum in 23 of 40 cases), so compare the objective, not the
            // matrix: ours must be at least as good, with the same rows and heights.
            var zo = Cluster.Linkage(y, method, optimalOrdering: true);
            var zs = new NdArray(D(c.GetProperty("zopt")), z.Shape[0], 4);
            Assert.True(AdjacentCost(zo, y) <= AdjacentCost(zs, y) + 1e-12, name + " optimal ordering worse than scipy's");
            var a = zo.ToArray(); var b = z.ToArray();
            for (var r = 0; r < z.Shape[0]; r++)
            {
                Assert.Equal(b[4 * r + 2], a[4 * r + 2]);
                Assert.Equal(new[] { b[4 * r], b[4 * r + 1] }.Order(), new[] { a[4 * r], a[4 * r + 1] }.Order());
            }
        }
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void FclusterCophenetInconsistent_MatchScipy(int index)
    {
        var (c, y, _, method) = Load(index);
        var name = $"{c.GetProperty("data").GetString()}/{method}";
        var z = new NdArray(D(c.GetProperty("z")), y.Length == 0 ? 0 : D(c.GetProperty("z")).Length / 4, 4);
        var (coef, coph) = Cluster.Cophenet(z, y);
        Close(c.GetProperty("coph_c").GetDouble(), coef, 1e-12, name + " cophenetic c");
        Close(D(c.GetProperty("coph")), coph, 0, name + " cophenetic distances");
        Close(D(c.GetProperty("inc")), Cluster.Inconsistent(z).ToArray(), 1e-12, name + " inconsistent");
        Close(D(c.GetProperty("inc3")), Cluster.Inconsistent(z, 3).ToArray(), 1e-12, name + " inconsistent d=3");
        Close(D(c.GetProperty("maxdists")), Cluster.Maxdists(z), 0, name + " maxdists");
        var mi = Cluster.Maxinconsts(z, Cluster.Inconsistent(z));
        Close(D(c.GetProperty("maxinconsts")), mi, 1e-12, name + " maxinconsts");
        foreach (var prop in c.GetProperty("fcluster").EnumerateObject())
        {
            var parts = prop.Name.Split(':');
            var crit = parts[0] switch { "distance" => FclusterCriterion.Distance, "maxclust" => FclusterCriterion.Maxclust, _ => FclusterCriterion.Inconsistent };
            var t = double.Parse(parts[1], System.Globalization.CultureInfo.InvariantCulture);
            var got = Cluster.Fcluster(z, t, crit);
            Assert.True(I(prop.Value).SequenceEqual(got), $"{name} fcluster {prop.Name}: expected {string.Join(",", I(prop.Value))}, got {string.Join(",", got)}");
        }
        var mm = Cluster.Fcluster(z, 3, FclusterCriterion.MaxclustMonocrit, monocrit: mi);
        Assert.True(I(c.GetProperty("fc_mmono")).SequenceEqual(mm), $"{name} maxclust_monocrit: expected {string.Join(",", I(c.GetProperty("fc_mmono")))}, got {string.Join(",", mm)}; MI {string.Join(",", mi)}");
    }

    private static void SameDendrogram(JsonElement e, DendrogramResult r, string what)
    {
        var ic = e.GetProperty("icoord").EnumerateArray().Select(D).ToList();
        var dc = e.GetProperty("dcoord").EnumerateArray().Select(D).ToList();
        Assert.Equal(ic.Count, r.Icoord.Count);
        for (var k = 0; k < ic.Count; k++)
        {
            Close(ic[k], r.Icoord[k], 1e-12, what + " icoord");
            Close(dc[k], r.Dcoord[k], 1e-12, what + " dcoord");
        }
        Assert.Equal(e.GetProperty("ivl").EnumerateArray().Select(v => v.GetString()!).ToList(), r.Ivl);
        Assert.Equal(I(e.GetProperty("leaves")), r.Leaves.ToArray());
        Assert.Equal(e.GetProperty("color_list").EnumerateArray().Select(v => v.GetString()!).ToList(), r.ColorList);
        Assert.Equal(e.GetProperty("leaves_color_list").EnumerateArray().Select(v => v.ValueKind == JsonValueKind.Null ? null : v.GetString()).ToList(), r.LeavesColorList);
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void DendrogramAndCutTree_MatchScipy(int index)
    {
        var (c, _, _, method) = Load(index);
        var name = $"{c.GetProperty("data").GetString()}/{method}";
        var zd = D(c.GetProperty("z"));
        var z = new NdArray(zd, zd.Length / 4, 4);
        var dmax = Enumerable.Range(0, zd.Length / 4).Max(i => zd[4 * i + 2]);
        SameDendrogram(c.GetProperty("den"), Cluster.Dendrogram(z), name);
        SameDendrogram(c.GetProperty("den_lastp"), Cluster.Dendrogram(z, p: 5, truncateMode: DendrogramTruncateMode.LastP,
            countSort: DendrogramSort.Descending, colorThreshold: 0.5 * dmax), name + " lastp");
        SameDendrogram(c.GetProperty("den_level"), Cluster.Dendrogram(z, p: 2, truncateMode: DendrogramTruncateMode.Level,
            distanceSort: DendrogramSort.Ascending), name + " level");
        if (c.GetProperty("cut").ValueKind == JsonValueKind.Null) return;
        var n = zd.Length / 4 + 1;
        var full = Cluster.CutTree(z);
        var expected = I(c.GetProperty("cut"));
        for (var col = 0; col < n; col++)
            for (var j = 0; j < n; j++) Assert.True(expected[col * n + j] == full[j, col], $"{name} cut_tree column {col} row {j}");
        var some = Cluster.CutTree(z, nClusters: [2, 4]);
        var e2 = I(c.GetProperty("cut_n"));
        for (var col = 0; col < 2; col++)
            for (var j = 0; j < n; j++) Assert.Equal(e2[col * n + j], some[j, col]);
    }

    [Fact]
    public void ScipyDocExample_WardAndFcluster()
    {
        // From the scipy fcluster docstring.
        var x = new NdArray([0, 0, 0, 1, 1, 0, 0, 4, 0, 3, 1, 4, 4, 0, 3, 0, 4, 1, 4, 4, 3, 4, 4, 3.0], 12, 2);
        var z = Cluster.Linkage(x, LinkageMethod.Ward);
        Close(8.16496581, z[10, 2], 1e-8, "root");
        Assert.Equal(new[] { 1, 1, 2, 3, 3, 4, 5, 5, 6, 7, 7, 8 }, Cluster.Fcluster(z, 1.1, FclusterCriterion.Distance));
        Assert.Equal(new[] { 1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4 }, Cluster.Fcluster(z, 3, FclusterCriterion.Distance));
        Assert.Equal(new[] { 1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4 }, Cluster.FclusterData(x, 4, FclusterCriterion.Maxclust, method: LinkageMethod.Ward));
        Assert.True(Cluster.IsMonotonic(z));
        Assert.Equal(12, Cluster.NumObsLinkage(z));
        Assert.True(Cluster.Correspond(z, Distance.Pdist(x)));
    }

    [Fact]
    public void Validation_RejectsMalformedLinkage()
    {
        Assert.False(Cluster.IsValidLinkage(new NdArray([0, 1, 1, 2, 0, 2, 2, 3.0], 2, 4))); // cluster 0 used twice
        Assert.False(Cluster.IsValidLinkage(new NdArray([0, 4, 1, 2, 1, 2, 2, 3.0], 2, 4))); // used before formed
        Assert.Throws<ArgumentException>(() => Cluster.Linkage(new NdArray([0, 0, 1, 1.0], 2, 2), LinkageMethod.Ward, DistanceMetric.Cityblock));
        Assert.Throws<ArgumentException>(() => Cluster.Linkage(new double[] { 1, 2 }));
        Assert.Throws<ArgumentException>(() => Cluster.Linkage(new double[] { 1, double.NaN, 2 }));
    }

    private static double AdjacentCost(NdArray z, double[] y)
    {
        var leaves = Cluster.LeavesList(z);
        var n = leaves.Length;
        var s = 0.0;
        for (var i = 0; i + 1 < n; i++)
        {
            int a = Math.Min(leaves[i], leaves[i + 1]), b = Math.Max(leaves[i], leaves[i + 1]);
            s += y[n * a - a * (a + 1) / 2 + (b - a - 1)];
        }
        return s;
    }

    [Fact]
    public void OptimalLeafOrdering_MinimisesAdjacentDistanceOnSmallTrees()
    {
        // Brute force over all 2^(n-1) child flips.
        var x = LcgNd(8, 2, 3);
        var y = Distance.Pdist(x);
        var z = Cluster.Linkage(y, LinkageMethod.Average);
        double Cost(NdArray zz)
        {
            var leaves = Cluster.LeavesList(zz);
            var s = 0.0;
            for (var i = 0; i + 1 < leaves.Length; i++)
            {
                int a = Math.Min(leaves[i], leaves[i + 1]), b = Math.Max(leaves[i], leaves[i + 1]);
                s += y[8 * a - a * (a + 1) / 2 + (b - a - 1)];
            }
            return s;
        }
        var best = double.PositiveInfinity;
        var za = z.ToArray();
        for (var mask = 0; mask < 1 << 7; mask++)
        {
            var c = (double[])za.Clone();
            for (var r = 0; r < 7; r++) if ((mask >> r & 1) == 1) (c[4 * r], c[4 * r + 1]) = (c[4 * r + 1], c[4 * r]);
            best = Math.Min(best, Cost(new NdArray(c, 7, 4)));
        }
        Close(best, Cost(Cluster.OptimalLeafOrdering(z, y)), 1e-12, "optimal cost");
    }
}
